1	#!/usr/bin/env node
2	import { parseArgs } from 'node:util';
3	import { CYCLE, monthlyCents } from '../src/cycles.js';
4	import { parseDate, todayIso } from '../src/dates.js';
5	import { toCsv } from '../src/export.js';
6	import { formatEuros, parseEuros } from '../src/money.js';
7	import { upcoming } from '../src/renewals.js';
8	import { load, save, storePath, validate } from '../src/store.js';
9	
10	const USAGE = `usage: subtrack <command> [options]
11	
12	  add <name> <price> [--every month|year] [--since YYYY-MM-DD]
13	  list
14	  total
15	  renewals [--within <days>]
16	  export
17	  remove <name>
18	
19	options for every command: --file <path>, --today YYYY-MM-DD`;
20	
21	function die(message, code = 1) {
22	  process.stderr.write(`subtrack: ${message}\n`);
23	  process.exit(code);
24	}
25	
26	// --every month|year (also monthly/yearly, m/y)
27	function cycleFlag(value = 'month') {
28	  return /^y/i.test(value) ? CYCLE.YEAR : CYCLE.MONTH;
29	}
30	
31	let parsed;
32	try {
33	  parsed = parseArgs({
34	    args: process.argv.slice(2),
35	    allowPositionals: true,
36	    options: {
37	      every: { type: 'string' },
38	      since: { type: 'string' },
39	      within: { type: 'string' },
40	      today: { type: 'string' },
41	      file: { type: 'string' },
42	      help: { type: 'boolean', short: 'h' },
43	    },
44	  });
45	} catch (err) {
46	  die(`${err.message}\n\n${USAGE}`, 2);
47	}
48	const { values: opts, positionals } = parsed;
49	const [command, ...args] = positionals;
50	if (opts.help || !command) {
51	  console.log(USAGE);
52	  process.exit(command || opts.help ? 0 : 2);
53	}
54	
55	const file = storePath(opts.file);
56	const today = opts.today === undefined ? todayIso() : parseDate(opts.today);
57	if (today === null) die(`--today must be a date (YYYY-MM-DD), got "${opts.today}"`, 2);
58	
59	let subs;
60	try {
61	  subs = load(file);
62	} catch (err) {
63	  die(err.message);
64	}
65	
66	switch (command) {
67	  case 'add': {
68	    const [name, priceText] = args;
69	    if (!name || priceText === undefined) die(`add needs a name and a price\n\n${USAGE}`, 2);
70	    const price = parseEuros(priceText);
71	    if (price === null) die(`"${priceText}" is not a price (try 12.99)`, 2);
72	    const since = opts.since === undefined ? today : parseDate(opts.since);
73	    if (since === null) die(`--since must be a date (YYYY-MM-DD), got "${opts.since}"`, 2);
74	    if (subs.some((s) => s.name.toLowerCase() === name.toLowerCase())) die(`${name} is already on the list`);
75	    const sub = { name, price, cycle: cycleFlag(opts.every), since };
76	    const problem = validate(sub);
77	    if (problem) die(problem, 2);
78	    subs.push(sub);
79	    save(file, subs);
80	    console.log(`Added ${name}: ${formatEuros(price)} ${sub.cycle}, ${formatEuros(monthlyCents(sub))} a month.`);
81	    break;
82	  }
83	  case 'list': {
84	    if (!subs.length) {
85	      console.log('No subscriptions yet. Add one with: subtrack add <name> <price>');
86	      break;
87	    }
